import React, { PropsWithChildren } from "react";
import clsx from "clsx";
import { Text as TextStyles } from "@airbus/styles";
import { createUseStyles } from "../../lib/styling";
import { CommonProps } from "../helperTypes";

type Props = PropsWithChildren<{
  /**
   * The typography color
   * @default determined from the `variant` prop
   */
  color?: "heading" | "primary" | "secondary" | "tertiary";
  /**
   * The html tag to be used
   * @default determined from the `variant` prop
   */
  component?: string;
  /**
   * Renders text with "Roboto Mono" monospace font family.
   * Useful to convey system messages for example.
   */
  isMono?: boolean;
  /**
   * The typography variant
   * @default medium
   */
  variant?:
    | "h1"
    | "h2"
    | "h3"
    | "h4"
    | "h5"
    | "h6"
    | "subH1"
    | "subH2"
    | "subH3"
    | "subH4"
    | "subH5"
    | "subH6"
    | "large"
    | "medium"
    | "small"
    | "xsmall";
  /** If `true`, remove bottom margin */
  noGutterBottom?: boolean;
}>;

export type TypographyProps = Props & CommonProps;

const useStyles = createUseStyles(TextStyles, "typography");

const variantMapping: any = {
  h1: "h1",
  h2: "h2",
  h3: "h3",
  h4: "h4",
  h5: "h5",
  h6: "h6",
  subH1: "h1",
  subH2: "h2",
  subH3: "h3",
  subH4: "h4",
  subH5: "h5",
  subH6: "h6",
  large: "div",
  medium: "div",
  small: "div",
  xsmall: "div",
};

const colorMapping: any = {
  h1: "heading",
  h2: "heading",
  h3: "heading",
  h4: "heading",
  h5: "heading",
  h6: "heading",
  subH1: "heading",
  subH2: "heading",
  subH3: "heading",
  subH4: "heading",
  subH5: "heading",
  subH6: "heading",
  large: "primary",
  medium: "primary",
  small: "primary",
  xsmall: "tertiary",
};

const Typography = (props: TypographyProps) => {
  const {
    children,
    className,
    color: colorProp,
    component,
    dark,
    isMono = false,
    noGutterBottom = false,
    tag,
    variant = "medium",
    ...rest
  } = props;
  const classes = useStyles();
  const color = colorProp || colorMapping[variant];
  const Component = tag || component || variantMapping[variant] || "span";

  return (
    <Component
      {...rest}
      className={clsx(className, classes[`_${variant}`], {
        [classes.root]: variant.indexOf("h") < 0 && variant.indexOf("subH") < 0,
        [classes._mono]: isMono,
        [classes._noGutter]: noGutterBottom,
        [classes._heading]: color === "heading",
        [classes._body]: color === "primary",
        [classes._label]: color === "secondary",
        [classes._legend]: color === "tertiary",
      })}
    >
      {children}
    </Component>
  );
};

export default Typography;
